    void ConfigureJob(LauncherJob job,ResourceProject? project=null)
    {
        job.Source=DownloadProvider.Load()?.Name??"本机操作";job.Icon=(homeGame.SelectedItem as GameInstance)?.Icon??InstanceIcons.Get("vanilla");
        if((project??resourceList.SelectedItem as ResourceProject) is ResourceProject p&&job.Name=="安装 "+p.Name){job.Category=p.Type;job.Source="Modrinth";job.IconUrl=p.IconUrl;job.Description=p.Description;job.Icon=InstanceIcons.Get(p.Type);}
        else if(job.Name.Contains("基岩版")){job.Icon=InstanceIcons.Get("bedrock");}else if(job.Name.StartsWith("导入整合包")){job.Category="modpack";job.Source="本地文件";}
    }
